#include <vector>
#include <cmath>

class Solution {
public:
    std::vector<int> findDisappearedNumbers(std::vector<int>& nums) {
        int n = nums.size();
        for (int x : nums) {
            int idx = std::abs(x) - 1;
            if (nums[idx] > 0) nums[idx] = -nums[idx];
        }
        std::vector<int> res;
        for (int i = 0; i < n; ++i) {
            if (nums[i] > 0) res.push_back(i + 1);
            else nums[i] = -nums[i];
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> findDisappearedNumbers(int[] nums) {
        int n = nums.length;
        for (int x : nums) {
            int idx = Math.abs(x) - 1;
            if (nums[idx] > 0) nums[idx] = -nums[idx];
        }
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums[i] > 0) res.add(i + 1);
            else nums[i] = -nums[i];
        }
        return res;
    }
}

